173	    ) -> Result<Conversation, MailError> {
174	        let conversation = match self {
175	            Self::Gmail(core) | Self::Synthetic(core) => {
176	                core.load_reply_context(r#ref, source_message_id)?
177	            }
178	        };
179	        validate_reply_conversation(&conversation, r#ref, source_message_id)?;
180	        if conversation
181	            .reply_context
182	            .as_ref()
183	            .is_none_or(|context| context.source_message_id != source_message_id)
184	        {
185	            return Err(MailError::ReplyUnavailable);
186	        }
187	        Ok(conversation)
