344	/// Managed app state retains its change-listener guard for the full app life.
345	#[derive(Default)]
346	struct AttachmentTransfers {
347	    active: HashMap<String, CancelToken>,
348	    cancelled: VecDeque<String>,
349	}
350	impl AttachmentTransfers {
351	    fn begin(&mut self, id: &str) -> Result<CancelToken, MailError> {
352	        if !mail_core::attachments::valid_id(id) {
353	            return Err(mail_core::attachments::invalid("requestId"));
354	        }
355	        if !self.active.is_empty() {
356	            return Err(MailError::Busy);
357	        }
358	        if self.cancelled.iter().any(|v| v == id) {
359	            return Err(MailError::AuthCancelled);
360	        }
361	        let token = CancelToken::default();
362	        self.active.insert(id.into(), token.clone());
363	        Ok(token)
364	    }
365	    fn cancel(&mut self, id: &str) {
366	        if let Some(token) = self.active.get(id) {
367	            token.cancel();
368	        }
369	        self.cancelled.push_back(id.into());
370	        while self.cancelled.len() > 64 {
371	            self.cancelled.pop_front();
372	        }
373	    }
374	}
