388	}
389	
390	impl DraftLifecycle {
391	    fn advance(&mut self) {
392	        self.session_epoch = self.session_epoch.wrapping_add(1);
393	    }
394	
395	    fn is_current(&self, epoch: u64) -> bool {
396	        self.session_epoch == epoch
397	    }
398	}
