418	/// Opens the fixture profile under `app_data_dir`: the synthetic core on its
419	/// own files. A legacy `mail.db` in the same directory is never opened here;
420	/// retiring it is the explicit, disclosed transition (`fixture_transition`).
421	/// The profile lock and `local-drafts` live in the same directory, so a second
422	/// writer is rejected.
423	fn open_fixture_backend(
424	    app_data_dir: &std::path::Path,
425	) -> Result<(Backend, std::path::PathBuf), Box<dyn std::error::Error>> {
426	    let profile_dir = app_data_dir.join("fixture-profile");
427	    let core = GmailCore::open_synthetic_profile(
428	        &profile_dir,
429	        mail_core::synthetic::WriteControls::from_env(),
430	        Arc::new(mail_core::clock::SystemClock),
431	    )?;
432	    Ok((Backend::Synthetic(core), profile_dir))
433	}
