450	fn validate_reply_conversation(
451	    conversation: &Conversation,
452	    expected_ref: &ConversationRef,
453	    source_message_id: &str,
454	) -> Result<(), MailError> {
455	    if &conversation.conversation_ref != expected_ref
456	        || conversation.context_complete != Some(true)
457	        || conversation.retained_snapshot_at.is_some()
458	        || conversation
459	            .messages
460	            .last()
461	            .map(|message| message.id.as_str())
462	            != Some(source_message_id)
463	    {
464	        return Err(MailError::ReplyUnavailable);
465	    }
466	    Ok(())
467	}
