469	/// Run all synchronous core/storage operations outside Tauri's async/UI threads.
470	async fn run_blocking<T, F>(backend: Backend, f: F) -> Result<T, MailError>
471	where
472	    F: FnOnce(&Backend) -> Result<T, MailError> + Send + 'static,
473	    T: Send + 'static,
474	{
475	    tauri::async_runtime::spawn_blocking(move || f(&backend))
476	        .await
477	        .map_err(|_| storage_failure(cause::TASK_JOIN))?
478	}
