901	#[tauri::command]
902	async fn create_draft(
903	    app: AppHandle,
904	    state: State<'_, AppState>,
905	    command: CreateDraft,
906	) -> Result<DraftReceipt, MailError> {
907	    let backend = state.backend.clone();
908	    let drafts = state.drafts.clone();
909	    let lifecycle = Arc::clone(&state.draft_lifecycle);
910	    let receipt = run_blocking(backend, move |backend| {
911	        let lifecycle_guard = lifecycle
912	            .lock()
913	            .map_err(|_| storage_failure(cause::LOCK_POISONED))?;
914	        let account = active_account(backend)?;
915	        if let Some(receipt) = drafts.lookup_create_receipt(&account, &command)? {
916	            return Ok(receipt);
917	        }
918	        match &command.source {
919	            DraftSource::NewMessage => drafts.create_draft(&account, &command, None),
920	            DraftSource::Reply {
921	                conversation,
922	                source_message_id,
923	            } => {
924	                if conversation.account_id != account.account_id {
925	                    return Err(MailError::ReplyUnavailable);
926	                }
927	                let displayed = backend.get_conversation(conversation)?;
928	                validate_reply_conversation(&displayed, conversation, source_message_id)?;
929	                let session_epoch = lifecycle_guard.session_epoch;
930	                drop(lifecycle_guard);
931	
932	                // This helper is a cache hit when metadata is ready. A legacy
933	                // metadata fetch is readonly and deliberately happens unlocked.
934	                let reply_conversation =
935	                    backend.load_reply_context(conversation, source_message_id)?;
936	
937	                let lifecycle_guard = lifecycle
938	                    .lock()
939	                    .map_err(|_| storage_failure(cause::LOCK_POISONED))?;
940	                if !lifecycle_guard.is_current(session_epoch)
941	                    || active_account(backend)?.account_id != account.account_id
942	                {
943	                    return Err(MailError::AuthRequired);
944	                }
945	                let current = backend.get_conversation(conversation)?;
946	                validate_reply_conversation(&current, conversation, source_message_id)?;
947	                if current.reply_context != reply_conversation.reply_context {
948	                    return Err(MailError::ReplyUnavailable);
949	                }
950	                drafts.create_draft(&account, &command, Some(&reply_conversation))
951	            }
952	        }
953	    })
954	    .await?;
955	    let _ = app.emit("drafts_changed", ());
956	    Ok(receipt)
957	}
