fn record(site: &'static Location<'static>, cause: &Cause) {
    if cause.kind == "already_logged" {
        return;
    }
    match cause.sqlite {
        Some((code, extended)) => log::error!(
            target: LOG_TARGET,
            "storage failure site={}:{} cause={} code={} extended={}",
            site.file(),
            site.line(),
            cause.kind,
            code,
            extended
        ),
        None => log::error!(
            target: LOG_TARGET,
            "storage failure site={}:{} cause={}",
            site.file(),
            site.line(),
            cause.kind
        ),
    }
}

